import {MODEL,create,advance,resolve,close,restore,activeTeam,activeClients,staff,costs,receivables,concentration,clientWork,chapter,reflection} from './model.js';
const app=document.querySelector('#app'),modal=document.querySelector('#modal'),KEY='company-life-save-v2',OLD_KEY='company-life-save-v1';
let config,cohort,s=null,draft,saveError='',brokenRaw='',legacy=false,busy=false,selected=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Math.round(v).toLocaleString('ja-JP'),money=v=>`${num(v)}万円`,seed=()=>crypto.getRandomValues(new Uint32Array(1))[0];
const period=q=>q===0?'創業の日':`${Math.floor((q-1)/4)+1}年目・${['春','夏','秋','冬'][(q-1)%4]}`;
const header=()=>`<header><a class="brand" href="./" aria-label="会社の一生"><span class="brand-mark">会</span><div><strong>会社の一生</strong><small>EVERY COMPANY HAS AN UNTOLD STORY</small></div></a><nav>${s?'<button data-do="history">これまでの歩み</button><button data-do="relationships">人とつながり</button>':''}<button data-do="data">この世界について</button><span class="demo">創業編 / 0.2</span></nav></header>`;
const footer=()=>`<footer class="footer-note"><span>境遇と偶然から生まれる、架空の会社の記録。</span><span>数値はゲーム用の仮置き。実測の統計はまだ採用していません。</span></footer>`;
function cohortFor(state){return cohort?.model===MODEL&&cohort?.dataVersion===state.config.version?cohort.groups[state.originId]:null;}
function comparison(state,moment='start'){
 const g=cohortFor(state);if(!g)return '';
 let text='';
 if(moment==='start')text=`この境遇で生成した${g.count}社は、${g.initialTeam}人から出発。創業資金の中央値は${money(g.initialCashMedian)}でした。`;
 else if(moment==='end')text=`同じ境遇で始めた${g.count}社の記録では、${g.longRelations}社に2年以上続く取引が残り、${g.changedTeam}社で創業時の仲間が会社を離れました。`;
 else{const type=state.pending?.type,key={large:'large',inquiry:'inquiry',crisis:'crisis',hiring:'hiring',team:'team',relationship:'relationship',delegation:'delegation',renewal:'renewal'}[type];text=key?`同じ境遇で始めた${g.count}社のうち、${g.decisionCompanies[key]||0}社の5年間に、この種類の節目がありました。`:`同じ境遇で始めた${g.count}社のうち、${g.referralCompanies}社に、以前の縁からの紹介が届きました。`;}
 return `<aside class="cohort-note"><div><span class="cohort-mark">◌</span><strong>ほかの、小さな会社たち</strong><span class="source-tag">デモ内の生成集計</span></div><p>${text}</p><button class="text-button" data-do="cohort">実際の企業統計とは異なります。集計条件を見る ↗</button></aside>`;
}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(s));saveError='';}catch{saveError='この会社の記録を自動保存できませんでした。閉じる前に「記録を書き出す」で残せます。';}}
function exportFile(raw,name){const url=URL.createObjectURL(new Blob([raw],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function welcome(){
 draft||=create(seed(),'こもれびソフト',config);const o=draft.origin;
 app.innerHTML=header()+`<main class="page beginning">${brokenRaw?`<div class="toast">${esc(saveError)} <button data-do="export-broken" class="text-button">元の記録を書き出す</button></div>`:''}${legacy?'<div class="legacy-note">以前の会社の記録があります。<a href="../legacy/">旧版で続きを開く →</a></div>':''}<div class="welcome"><section class="intro"><div class="eyebrow">境遇と偶然から生まれる、一社の歴史</div><h1>次は、どんな<br>会社になるだろう。</h1><p>最初から仕事のある会社も、<br>仲間だけが頼りの会社もある。<br>季節を見届け、ときどき、大切なことを決める。<br>あなたが出会う一社の、最初の5年間。</p></section><div class="hero-art origin-${o.id}"><img src="../assets/studio.png" alt="これから会社の歴史が始まる、小さな事務所"><span class="art-note">会社の数だけ、はじまりがある。</span></div></div><section class="origin-sheet"><div class="origin-heading"><div><div class="eyebrow">今回めぐりあった、創業の境遇</div><h2>${esc(o.headline)}</h2></div><button class="text-button" data-do="reroll">↻ 別のめぐりあわせを見る</button></div><div class="origin-layout"><div><div class="origin-pills">${config.origins.map(b=>`<button data-origin="${b.id}" aria-pressed="${b.id===o.id}" class="origin-pill ${b.id===o.id?'active':''}">${esc(b.label)}</button>`).join('')}</div><p class="origin-description">${esc(o.description)}</p><div class="origin-edges"><span>持っているもの<br><b>${esc(o.strength)}</b></span><span>気がかりなこと<br><b>${esc(o.tension)}</b></span></div><div class="region-label">${esc(o.region)} · 開発経験 ${draft.experience}年</div></div><div class="start-column"><div class="conditions"><div><small>創業時の手元資金</small><strong>${num(draft.cash)}</strong><span> 万円</span></div><div><small>あなたを含めた仲間</small><strong>${staff(draft)+1}</strong><span> 人</span></div><div><small>継続顧客</small><strong>${draft.clients.length}</strong><span> 社</span></div></div><p class="start-finance">通常費用 ${money(costs(draft))}/期 · 借入 ${money(draft.debt)}（資金に含む）</p><div class="field"><label for="company">この会社の名前</label><input id="company" maxlength="24" value="${esc(draft.name)}" autocomplete="off"></div><button class="primary start" data-do="start">この会社の歩みを、見届ける <span class="arrow">→</span></button></div></div>${comparison(draft)}</section>${footer()}</main>`;
}
function visibleEvents(){const qs=s.batch?.length?s.batch:[s.q];let events=s.events.filter(e=>qs.includes(e.q));if(s.q===0)return s.events.filter(e=>e.q===0);return events.filter(e=>e.kind!=='world').slice(-5);}
function eventView(e){const causes=e.causes.map(id=>s.events.find(p=>p.id===id)).filter(Boolean);return `<article class="story-event ${e.kind}"><span class="event-dot">${e.kind==='risk'?'!':e.kind==='turning'?'✧':e.kind==='choice'?'↗':'·'}</span><div><div class="event-meta">${period(e.q)}${e.topic==='people'?' / 仲間のこと':e.topic==='relationship'?' / 続いてきた関係':''}</div><h3>${esc(e.title)}</h3><p>${esc(e.text)}</p>${causes.length?`<button class="causal-link" data-event="${e.id}">↳ ${esc(causes[0].title)} から続く出来事</button>`:''}</div></article>`;}
function statusStrip(){return `<div class="status-strip"><div><label>手元資金</label><strong class="${s.cash<costs(s)*1.3?'negative':''}">${num(s.cash)}<small>万円</small></strong><span>${s.q?`${s.last.deltaCash>=0?'＋':''}${money(s.last.deltaCash)} / 直近の期`:'創業時の資金'}</span></div><div><label>前期の売上 / 利益</label><strong>${s.q?num(s.last.revenue):'—'}<small>/ ${s.q?num(s.last.profit):'—'} 万円</small></strong><span>入金待ち ${money(receivables(s))}</span></div><div><label>一緒に働く人</label><strong>${staff(s)+1}<small>人</small></strong><span>取引先 ${activeClients(s).length}社 / 借入 ${money(s.debt)}</span></div></div>`;}
function scene(){const team=activeTeam(s);return `<div class="office story-office origin-${s.originId}"><img src="../assets/studio.png" alt="会社の事務所のイメージ"><div class="scene-top"><span class="scene-chip">${esc(chapter(s))}</span><span class="scene-chip">${['☁ 向かい風','◌ いつもの景気','☀ 追い風'][s.macro]}</span></div><div class="scene-bottom"><div class="team-cast"><div class="cast-member"><i class="person"></i><small>あなた</small></div>${team.slice(0,7).map(p=>`<div class="cast-member"><i class="person ${p.founding?'founder':'newcomer'}"></i><small>${esc(p.name)}</small></div>`).join('')}</div><span class="scene-caption">${s.style==='companion'?'長く知る相手と、次の季節へ。':s.fatigue>60?'忙しさの向こうで、仲間の声も。':staff(s)>=3?'誰と、どう働く会社になるだろう。':activeClients(s).length===0?'最初の「お願いします」を、待っている。':'目の前の約束が、会社の歴史になる。'}</span></div></div>`;}
function journey(){const e=visibleEvents(),count=s.batch?.length||0;return `<section class="journey" aria-live="polite"><div class="section-heading"><h2>${s.q===0?'はじまりの一ページ':count>1?`${count*3}か月のあいだに`:'この季節に起きたこと'}</h2><span>${s.q===0?'PROLOGUE':s.batch?.length>1?`${period(s.batch[0])} → ${period(s.q)}`:period(s.q)}</span></div>${count>1?`<p class="quiet-summary">平常の仕事を${count}四半期、重ねました。${s.batch.map(q=>s.history[q-1]).filter(Boolean).filter(h=>h.profit>=0).length}期は利益が出ています。小さな変化も、すべて記録に残っています。</p>`:''}${e.length?e.map(eventView).join(''):`<article class="quiet-page"><span>◌</span><h3>いつもの仕事を、いつもの相手と。</h3><p>大きな出来事はなくても、仕事と支払いを重ねた時間がある。</p></article>`}</section>`;}
function nextPanel(){const d=s.pending;if(d){return `<aside class="decision-panel"><div class="decision-label"><span>◆</span> ここで、大切な判断</div><div class="eyebrow">${period(d.at)}に向けて</div><h2>${esc(d.title)}</h2><p class="decision-context">${esc(d.text)}</p><div class="decision-options" role="group" aria-label="この節目での判断">${d.options.map(a=>`<button class="story-choice ${selected===a.id?'selected':''}" data-choice="${a.id}" aria-pressed="${selected===a.id}"><span class="option-marker">${selected===a.id?'●':'○'}</span><span><strong>${esc(a.title)}</strong><small>${a.cost?`今期の確定支出 ${a.cost}万円`:'追加の初期支出なし'}</small><p>${esc(a.desc)}</p><span class="choice-risk">${esc(a.effect)}</span></span></button>`).join('')}</div><button class="primary confirm-decision" data-do="decide" ${selected?'':'disabled'}>この判断で、次の季節へ <span class="arrow">→</span></button><p class="save-state">決めた方針で3か月を進め、実際の経過を確かめます。</p>${comparison(s,'turn')}</aside>`;}
 return `<aside class="observe-panel"><div class="eyebrow">次のページを、めくる</div><h2>${s.q===0?'この境遇から、<br>何が始まるだろう。':s.last.events.some(e=>e.topic==='people')?'この顔ぶれで、<br>次の季節へ。':'この会社の、<br>続きを見てみよう。'}</h2><p>いつもの仕事は、そのまま進みます。<br>相談や転機が訪れたら、立ち止まります。</p><button class="primary observe-next" data-do="advance">${s.q===0?'最初の季節を見届ける':'続きを見届ける'} <span class="arrow">→</span></button><div class="observe-rhythm"><span>季節を重ねる</span><i>···</i><span>出来事に出会う</span><i>···</i><b>ときどき決める</b></div><p class="save-state">平常期は最大9か月までまとめて進みます。</p><div class="relationship-preview"><div class="section-heading"><h3>いま、会社を支える縁</h3><button data-do="relationships" class="text-button">すべて →</button></div>${activeClients(s).slice(0,3).map(c=>`<div class="bond-row"><span class="bond-avatar">${esc(c.name[0])}</span><div><strong>${esc(c.name)}</strong><small>${c.since===0?'創業の頃から':`${period(c.since)}から`} / ${s.q-c.since>=8?'2年以上のつながり':'少しずつ重ねる関係'}</small></div></div>`).join('')||'<p class="empty-bonds">最初の継続顧客は、まだいません。仲間と出会いを待っています。</p>'}</div>${s.q>=2?comparison(s,'turn'):''}</aside>`;}
function render(){if(!s){welcome();return;}if(s.ended){result();return;}app.innerHTML=header()+`<main class="page story-page">${saveError?`<div class="toast">${esc(saveError)} <button class="text-button" data-do="export">記録を書き出す</button></div>`:''}<div class="masthead"><div><div class="eyebrow">${esc(s.origin.label)} / 創業編</div><h1>${esc(s.name)}</h1></div><div class="quarter"><strong>${period(s.q)}</strong><small>${s.q===0?'まだ、何も決まっていない':`創業から${s.q*3}か月 / 5年の観測記録`}</small><div class="progress" aria-label="20四半期のうち${s.q}期を経過">${Array.from({length:20},(_,i)=>`<i class="${i<s.q?'done':''}"></i>`).join('')}</div></div></div><div class="chronicle-grid"><div>${scene()}${statusStrip()}${journey()}<details class="accounting"><summary>会社の状態と、お金の内訳を見る　＋</summary>${ledger()}<div class="section-heading"><h3>仕事と負担</h3></div><p class="small-note">仕事の充足率 ${num(s.last.load*100)}% / 疲労 ${num(s.fatigue)}/100 / 処理倍率 ${s.skill.toFixed(2)}<br>未完了の仕事 ${money(s.backlog)} / 顧客集中 ${num(concentration(s)*100)}%</p></details></div>${nextPanel()}</div><div class="page-actions"><span>${saveError?'△ 未保存':'◌ ここまでの記録は自動保存されています'}</span><div><button data-do="export" class="text-button">記録を書き出す ↓</button><button data-do="close-company" class="text-button">経営をここで区切る</button></div></div>${footer()}</main>`;}
function ledger(){const l=s.last;const rows=s.q?[[`期首の現金`,money(l.startCash)],['納品した仕事の売上',money(l.revenue)],['給与・報酬・固定費・施策・外注費',`−${money(l.operating)}`],['借入利息',`−${money(l.interest)}`],['当期利益 = 売上 − 費用 − 利息',money(l.profit)],['実際に回収した現金',`＋${money(l.collections)}`],['新規借入（売上に含めない）',`＋${money(l.borrow)}`],['返済元本（費用に含めない）',`−${money(l.repay)}`],['期末現金 = 期首 + 回収 + 借入 − 費用 − 利息 − 返済',money(s.cash)]]:[];return `<table class="ledger"><tbody>${[...rows,['入金待ちの売掛金',money(receivables(s))],['借入残高',money(s.debt)],['現在の体制での通常費用',`${money(costs(s))} / 四半期`]].map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`).join('')}</tbody></table>`;}
function chart(metric='cash',label='手元資金 / 万円'){const values=[metric==='cash'?s.initial.cash:metric==='staff'?s.initial.staff+1:0,...s.history.map(h=>metric==='staff'?h.staff+1:h[metric])];const lo=Math.min(0,...values),hi=Math.max(1,...values),x=i=>45+i/Math.max(1,values.length-1)*485,y=v=>135-(v-lo)/(hi-lo)*110;return `<div class="chart-label"><span>${label}</span><span>創業 → ${s.q*3}か月</span></div><svg class="chart" viewBox="0 0 550 160" role="img" aria-label="${label}。創業時${num(values[0])}から現在${num(values.at(-1))}"><line x1="45" y1="25" x2="530" y2="25"/><line x1="45" y1="135" x2="530" y2="135"/><text x="0" y="29">${num(hi)}</text><text x="0" y="139">${num(lo)}</text><polyline points="${values.map((v,i)=>`${x(i)},${y(v)}`).join(' ')}"/>${values.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="2.7"><title>${period(i)}: ${num(v)}</title></circle>`).join('')}<text x="45" y="157">創業</text><text x="470" y="157">${s.q*3}か月</text></svg>`;}
function timeline(all=false){let ev=s.events.filter(e=>all||e.major||e.kind==='start');if(!all&&ev.length>9){const picks=[ev[0],...ev.filter(e=>['choice','turning','risk'].includes(e.kind)).slice(0,5),...ev.slice(-3)];ev=[...new Map(picks.map(e=>[e.id,e])).values()].sort((a,b)=>Number(a.id.slice(1))-Number(b.id.slice(1)));}return `<div class="full-timeline">${ev.map(eventView).join('')}</div>`;}
function result(){const notes=reflection(s);const title=s.ended==='five-years'?'ひとつの創業編が、ここに。':s.ended==='closed'?'あなたが選んだ、ひとつの区切り。':'続かなかった日々にも、物語がある。';app.innerHTML=header()+`<main class="page result"><section class="result-top"><div class="eyebrow">${s.ended==='five-years'?'創業編、おわり。会社の物語はこの先へ。':'ここまでの歩みを、振り返る。'}</div><h1>${title}</h1><p>${esc(s.name)} / ${esc(s.origin.label)} / ${s.q*3}か月の記録</p>${s.ended==='insolvent'?'<p>四半期末の資金が不足し、ゲーム上の経営継続が難しくなりました。</p>':''}</section><section class="memory-panel"><div class="eyebrow">あなたの会社が、経験したこと</div>${notes.map(n=>`<article><h2>${esc(n.title)}</h2><p>${esc(n.text)}</p></article>`).join('')}</section><div class="result-body"><section><img class="result-image" src="../assets/studio.png" alt="この会社の拠点のイメージ"><div class="result-stats"><div><small>始まりと、今の人数</small><strong>${s.initial.staff+1} → ${staff(s)+1}人</strong></div><div><small>残った取引先</small><strong>${activeClients(s).length}社</strong></div><div><small>今の手元資金</small><strong>${num(s.cash)}万円</strong></div></div><div style="margin-top:30px">${chart()}${chart('staff','一緒に働く人 / 人')}${chart('revenue','四半期の売上 / 万円')}</div>${comparison(s,'end')}<details><summary>最後の会計を見る</summary>${ledger()}</details></section><section><div class="section-heading"><h2>会社に残った、転機の記録</h2><button data-do="history" class="text-button">全記録 →</button></div>${timeline()}</section></div><div class="result-actions"><button class="primary" data-do="new">別の一社を見届ける <span class="arrow">→</span></button><button class="text-button" data-do="replay">同じ境遇・条件で、もう一度</button><button class="text-button" data-do="export">この会社の記録を書き出す ↓</button></div>${footer()}</main>`;}
function show(title,body){modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" data-do="dismiss" aria-label="閉じる">×</button></div>${body}`;if(!modal.open)modal.showModal();}
function relationships(){show('この会社と、縁のある人たち',`<div class="eyebrow">いま、一緒に働く人</div><div class="people-list">${activeTeam(s).map(p=>`<article><strong>${esc(p.name)}</strong><p>${esc(p.role)} / ${p.founding?'創業から一緒':`${period(p.joined)}に入社`} / 報酬${money(p.salary)}/期</p></article>`).join('')||'<p>今は、創業者ひとりで会社を回しています。</p>'}</div>${s.people.some(p=>!p.active)?`<div class="eyebrow">別の道へ進んだ仲間</div><div class="people-list">${s.people.filter(p=>!p.active).map(p=>`<article><strong>${esc(p.name)}</strong><p>${p.founding?'創業の日':period(p.joined)}から${period(p.left)}まで。${esc(p.leftReason)}</p></article>`).join('')}</div>`:''}<div class="eyebrow">取引先との関係</div>${s.clients.map(c=>`<div class="relationship-card"><strong>${esc(c.name)}</strong><span>${c.active?'継続中':'今回の取引は終了'}</span><p>${c.since===0?'創業時から':`${period(c.since)}から`}のつながり / ${c.active?`基準の仕事量 ${money(clientWork(s,c))}/期`:'継続契約には至らなかった'}${c.renewed?' / 続ける関係を考えた相手':''}</p>${c.sourceEvent?`<button class="causal-link" data-event="${c.sourceEvent}">この関係の、はじまりを見る ↗</button>`:''}</div>`).join('')||'<p>継続顧客は、まだいません。</p>'}${s.contacts.length?`<details><summary>相談した相手、つながらなかった話も見る</summary>${s.contacts.map(c=>`<p><b>${esc(c.name)}</b> / ${({available:'相談が届いている',passed:'今回は見送った',declined:'大口の相談を見送った',trial:'試作を進めた',negotiating:'契約を相談した',won:'契約につながった',lost:'契約に至らなかった'})[c.status]||esc(c.status)}</p>`).join('')}</details>`:''}`);}
function explainChain(eventId){let e=s.events.find(e=>e.id===eventId);if(!e)return;const chain=[],visited=new Set();function visit(e){if(!e||visited.has(e.id))return;visited.add(e.id);for(const id of e.causes)visit(s.events.find(p=>p.id===id));chain.push(e);}visit(e);show('あの出来事から、ここまで',`<p>実際に記録された関係だけをたどっています。</p><ol class="chain-list">${chain.map(e=>`<li><small>${period(e.q)}</small><h3>${esc(e.title)}</h3><p>${esc(e.text)}</p></li>`).join('')}</ol>`);}
function showCohort(){const state=s||draft,g=cohortFor(state);show('ほかの会社たちの、集計条件',g?`<span class="assumption-label">ゲーム内で実行した会社の集計 / 実際の企業統計ではありません</span><p>同じ境遇ごとに${g.count}社を、新しいモデルで創業から5年または資金不足まで実行しました。節目の選択は、可能な案から一様に抽選しています。会社ごとに乱数が異なります。</p><p>開始時の「同じ境遇」は、${esc(state.origin.label)}という基本形を指します。あなたと資金・選択・出来事が完全に同じ会社ではありません。この集計から、これから起こることの確率や、あなたの順位を計算していません。</p><table class="ledger"><tr><td>対象の生成会社</td><td>${g.count}社</td></tr><tr><td>5年まで続いた会社</td><td>${g.survived}社</td></tr><tr><td>資金が不足した会社</td><td>${g.insolvent}社</td></tr><tr><td>2年以上の取引が残った会社</td><td>${g.longRelations}社</td></tr><tr><td>以前の縁からの紹介が届いた会社</td><td>${g.referralCompanies}社</td></tr></table><p>モデル版 ${esc(cohort.model)} / 設定版 ${esc(cohort.dataVersion)}<br>現実の統計は、対象・出典・利用条件を確認してから追加します。</p>`:'このモデル・設定版に対応する生成集計は、まだありません。');}
function data(){show('この世界について',`<p>季節を見届け、ときどき重要な判断をする経営シミュレーションです。平常期は最大9か月をまとめて進み、出来事や相談が生まれたときに止まります。20四半期で「創業編」を振り返ります。</p><span class="assumption-label">現在の数値・確率・創業条件は、すべてゲーム上の仮置き</span><p>会社の境遇は、顧客と独立した経験者・顧客のいない創業チーム・地元の縁に支えられた会社の3種類。仲間や顧客を個別に記録し、失注後の紹介、受注からの採用、契約終了後の固定費などを履歴から計算します。</p><p>「ほかの会社たち」は同じモデルで実際に生成した会社の集計です。公的統計や実際の企業の比率とは区別しています。実際の統計は未採用で、現実の成功・廃業確率を示すものではありません。</p><details><summary>お金の計算と、省略していること</summary><p>納品した仕事を売上に、給与・役員報酬・固定費・施策費・外注費・利息を費用に計上します。通常は売上の55%を当期、残りを次期に回収。遅延時は当期回収分も次期へ。借入は利益へ加えず、元本返済は費用に含めません。</p><p>四半期末にまとめて回収・支払を判定します。税・減価償却・貸倒・家計・法的倒産手続を省略。選択肢の融資はゲーム上必ず実行。事務所の画像は共通のイメージで、実際の仲間は人物表示に反映されます。</p></details><details><summary>保存と、同じ条件での再現</summary><p>四半期の確定時と、相談が届いた時点を自動保存します。相談を見て再読み込みしても抽選は変わりません。乱数状態・設定値・モデル版を記録。同じ初期条件と選択列で同じ結果を再現できます。</p><p>モデル版 ${MODEL} / 設定版 ${esc((s||draft)?.config.version||config.version)}<br>旧版の記録は置き換えず、<a href="../legacy/">旧版画面から再開できます</a>。新しい会社での保存枠は1社です。</p></details><p><a href="../requirements.html" target="_blank" rel="noopener">改修した要件と設計を見る ↗</a></p><button class="text-button" data-do="cohort">デモ内の生成集計について見る →</button>`);}
function progress(operation){if(busy)return;busy=true;try{s=operation();selected=null;persist();render();if(s.ended)window.scrollTo(0,0);else document.querySelector(s.pending?'.decision-panel':'.journey')?.scrollIntoView({behavior:'smooth',block:'start'});}catch(err){show('進行を止めました',`<p>${esc(err.message)}</p>`);}finally{busy=false;}}
function start(){const name=document.querySelector('#company').value.trim()||'こもれびソフト';const run=()=>{s=create(draft.seed,name,draft.config,draft.originId);brokenRaw='';selected=null;persist();render();window.scrollTo(0,0);};if(brokenRaw){show('元の記録を残して、新しく始める',`<p>この版で読み込めない記録が残っています。必要なら先に書き出してください。新しい会社を始めると、この版の保存枠が置き換わります。</p><div class="modal-actions"><button class="text-button" data-do="export-broken">元の記録を書き出す</button><button class="primary" id="confirm-start">新しい会社を始める</button></div>`);document.querySelector('#confirm-start').onclick=()=>{modal.close();run();};}else run();}
function handle(e){const choice=e.target.closest('[data-choice]');if(choice){selected=choice.dataset.choice;const y=window.scrollY;render();window.scrollTo(0,y);document.querySelector(`[data-choice="${selected}"]`)?.focus({preventScroll:true});return;}const origin=e.target.closest('[data-origin]');if(origin){const name=document.querySelector('#company').value;draft=create(seed(),name,config,origin.dataset.origin);welcome();return;}const event=e.target.closest('[data-event]');if(event){explainChain(event.dataset.event);return;}const action=e.target.closest('[data-do]')?.dataset.do;if(!action)return;
 if(action==='dismiss'){modal.close();return;}if(action==='data'){data();return;}if(action==='cohort'){showCohort();return;}if(action==='relationships'){relationships();return;}if(action==='reroll'){const name=document.querySelector('#company').value;let next;do{next=create(seed(),name,config);}while(next.originId===draft.originId);draft=next;welcome();return;}if(action==='start'){start();return;}
 if(action==='advance'){progress(()=>advance(s));return;}if(action==='decide'&&selected){progress(()=>resolve(s,selected));return;}if(action==='history'){show('この会社が、歩いてきたこと',`<p>${esc(s.name)} / ${s.q*3}か月 / ${s.decisions.length}回の判断</p>${chart()}${timeline(true)}`);return;}
 if(action==='export'||action==='export-broken'){exportFile(action==='export'?JSON.stringify(s,null,2):brokenRaw,'company-life-record.json');return;}
 if(action==='close-company'){show('この会社の経営を、ここで区切る',`<p>ここまでの出来事と選択を振り返ります。この記録での経営は再開できません。同じ創業条件での再プレイはできます。</p><div class="modal-actions"><button class="primary" data-do="confirm-close">区切りをつけて、歩みを読む</button><button class="text-button" data-do="dismiss">まだ続きを見たい</button></div>`);return;}
 if(action==='confirm-close'){modal.close();progress(()=>close(s));return;}if(action==='new'){s=null;draft=create(seed(),'こもれびソフト',config);welcome();window.scrollTo(0,0);return;}if(action==='replay'){progress(()=>create(s.seed,s.name,s.config,s.originId));window.scrollTo(0,0);}
}
app.addEventListener('click',handle);modal.addEventListener('click',handle);modal.addEventListener('click',e=>{if(e.target===modal)modal.close();});
try{const r=await Promise.all([fetch('model-data.json'),fetch('cohort.json').catch(()=>null)]);if(!r[0].ok)throw Error('設定を読み込めません');config=await r[0].json();if(r[1]?.ok)cohort=await r[1].json();try{legacy=!!localStorage.getItem(OLD_KEY);const raw=localStorage.getItem(KEY);if(raw){try{s=restore(raw);}catch(err){brokenRaw=raw;saveError=err.message;}}}catch{saveError='このブラウザでは保存を利用できません。';}render();}catch(err){app.innerHTML=`<main class="page"><h1>会社の扉を開けませんでした。</h1><p>${esc(err.message)}</p><button onclick="location.reload()">もう一度開く</button></main>`;}
